@pytest.mark.parametrize("prompt_uri", ["prompts:/shared/1", "prompts:/shared@production"])
@pytest.mark.parametrize("configuration", ["registry", "tracking", "global"])
def test_load_prompt_cache_isolated_by_registry(
    prompt_registry_clients, prompt_uri, configuration, monkeypatch
):
    monkeypatch.setattr("mlflow.tracking._model_registry.utils._registry_uri", None)
    monkeypatch.delenv("MLFLOW_REGISTRY_URI", raising=False)
    clients = []
    for client in prompt_registry_clients:
        if configuration == "tracking":
            client = MlflowClient(tracking_uri=client._registry_uri)
        elif configuration == "global":
            monkeypatch.setenv("MLFLOW_REGISTRY_URI", client._registry_uri)
            client = MlflowClient(tracking_uri=client.tracking_uri)
        clients.append(client)
    first, second = clients
    for client, template in [(first, "First registry"), (second, "Second registry")]:
        client.register_prompt("shared", template=template)
        client.set_prompt_alias("shared", "production", 1)

    first_prompt = first.load_prompt(prompt_uri)
    second_prompt = second.load_prompt(prompt_uri)
    assert first_prompt.template == "First registry"
    assert second_prompt.template == "Second registry"

    for client, prompt in [(first, first_prompt), (second, second_prompt)]:
        assert client.load_prompt(prompt_uri) is prompt
        other_client = MlflowClient(registry_uri=client._registry_uri)
        assert other_client.load_prompt(prompt_uri) is prompt


