        ("delete_prompt_alias", ("shared", "production"), "delete_prompt_alias", "production"),
        ("set_prompt_version_tag", ("shared", "1", "tag", "new"), "set_prompt_version_tag", None),
        ("delete_prompt_version_tag", ("shared", "1", "tag"), "delete_prompt_version_tag", None),
        ("delete_prompt_version", ("shared", "1"), "delete_prompt_version", None),
        ("delete_prompt", ("shared",), "delete_prompt", None),
    ],
)
def test_prompt_cache_invalidation_isolated_by_registry(
    prompt_registry_clients, method, args, store_method, invalidated_alias, fails
):
    first, second = prompt_registry_clients
    cache = PromptCache.get_instance()
    entries = []
    for client in (first, second):
        client.register_prompt("shared", template="Original", tags={"tag": "old"})
        client.set_prompt_alias("shared", "production", 1)
        for uri in ["prompts:/shared/1", "prompts:/shared@production", "prompts:/shared@latest"]:
            prompt = client.load_prompt(uri)
            key = PromptCacheKey.from_uri(uri, registry_uri=client._registry_uri)
            entries.append((key, prompt))

    if fails:
        with mock.patch.object(
            first._get_registry_client(), store_method, side_effect=MlflowException("Failed mutation")
        ) as mutation:
            with pytest.raises(MlflowException, match="Failed mutation"):
                getattr(first, method)(*args)
            mutation.assert_called_once()
    else:
        getattr(first, method)(*args)

    for key, prompt in entries:
        invalidated = (
            not fails
            and key.registry_uri == first._registry_uri
            and (invalidated_alias is None or key.alias == invalidated_alias)
        )
        assert cache.get(key) is (None if invalidated else prompt)


